// Open Wikipedia page for The Miseducation of Lauryn Hill
const tabRes = await tool.tabs_create({ url: "https://en.wikipedia.org/wiki/The_Miseducation_of_Lauryn_Hill" });
const tab4Id = tabRes.details.tabId;
console.log("Created tab 4:", tab4Id);

await tool.wait_for({ tabId: tab4Id, condition: "load_state", value: "load", timeout_ms: 15000 });

// Extract track listing
const trackInfo = await browserjs(tab4Id, () => {
  // Find track listing table
  const trackTables = Array.from(document.querySelectorAll("table.tracklist"));
  let tracks = [];
  trackTables.forEach(table => {
    const rows = Array.from(table.querySelectorAll("tr"));
    rows.forEach(row => {
      const titleCell = row.querySelector("td:nth-child(2), td.tracklist-title");
      if (titleCell) {
        // Remove quotes and extra text
        const text = titleCell.innerText.trim().replace(/^"|"$/g, "");
        if (text && !text.includes("Title") && !text.includes("Length")) {
          tracks.push(text);
        }
      }
    });
  });

  // Fallback if not captured via specific class
  if (tracks.length === 0) {
    const ols = Array.from(document.querySelectorAll(".track-list, ol"));
    ols.forEach(ol => {
      const items = Array.from(ol.querySelectorAll("li")).map(li => li.innerText.trim());
      if (items.length > 5) tracks.push(...items);
    });
  }

  return {
    title: document.title,
    url: window.location.href,
    tracks: tracks.slice(0, 20)
  };
});

console.log("Track info:", JSON.stringify(trackInfo, null, 2));

